// SOURCE OF TRUTH — replace with your Supabase / Postgres / Google Sheets node.
// One item per conversion, tagged destination: meta | google | both.
// Hashed: email, phone, name, city, state, zip, country. Plain: external_id + device/click IDs.
// ONLY first-party consented data. Never append PII from third-party sources.
return [
  { json: { destination: 'both',   email: 'user@example.com ', phone: '+1234567890', first_name: 'Jane', last_name: 'Doe', city: 'San Francisco', state: 'CA', zip: '94103', country: 'US', external_id: 'crm_1001', client_ip_address: '203.0.113.10', client_user_agent: 'Mozilla/5.0', fbc: '', fbp: '', value: 2400, currency: 'USD', event_name: 'Purchase', event_time: 0, event_id: 'conv_1001' } },
  { json: { destination: 'meta',   email: 'user@example.com',           phone: '4155550111',        first_name: 'Sam',  last_name: 'Lee', city: 'Austin',        state: 'TX', zip: '73301', country: 'US', external_id: 'crm_1002', client_ip_address: '203.0.113.11', client_user_agent: 'Mozilla/5.0', fbc: '', fbp: '', value:  900, currency: 'USD', event_name: 'Purchase', event_time: 0, event_id: 'conv_1002' } },
  { json: { destination: 'google', email: 'user@example.com',            phone: '4155550122',        first_name: 'Ava',  last_name: 'Ng',  city: 'Denver',        state: 'CO', zip: '80202', country: 'US', external_id: 'crm_1003', client_ip_address: '203.0.113.12', client_user_agent: 'Mozilla/5.0', fbc: '', fbp: '', value: 1500, currency: 'USD', event_name: 'Purchase', event_time: 0, event_id: 'conv_1003' } },
];

const norm = (k, v) => {
  v = (v == null ? '' : String(v)).trim();
  if (!v) return '';
  if (k === 'ph') return v.replace(/[^0-9]/g, '');
  if (k === 'country') return v.toLowerCase().slice(0, 2);
  if (k === 'zp') return v.toLowerCase().replace(/[\s-]/g, '');
  return v.toLowerCase().replace(/\s+/g, '');
};
const FIELDS = [['email','em'],['phone','ph'],['first_name','fn'],['last_name','ln'],['city','ct'],['state','st'],['zip','zp'],['country','country']];
const PLAIN_META = ['external_id','fbc','fbp','client_ip_address','client_user_agent'];
// Expand each conversion into one item per HASHABLE identifier, normalized. The Crypto
// node then loops over all of these. external_id + device/click IDs are NOT expanded here.
const deals = $input.all().map((i) => i.json);
const out = [];
deals.forEach((d, idx) => {
  for (const [src, key] of FIELDS) {
    const val = norm(key, d[src]);
    if (val) out.push({ json: { dealIdx: idx, fieldKey: key, toHash: val } });
  }
});
return out;

const norm = (k, v) => {
  v = (v == null ? '' : String(v)).trim();
  if (!v) return '';
  if (k === 'ph') return v.replace(/[^0-9]/g, '');
  if (k === 'country') return v.toLowerCase().slice(0, 2);
  if (k === 'zp') return v.toLowerCase().replace(/[\s-]/g, '');
  return v.toLowerCase().replace(/\s+/g, '');
};
const FIELDS = [['email','em'],['phone','ph'],['first_name','fn'],['last_name','ln'],['city','ct'],['state','st'],['zip','zp'],['country','country']];
const PLAIN_META = ['external_id','fbc','fbp','client_ip_address','client_user_agent'];
// Collapse hashed items back per conversion. hashed = SHA-256 PII; plainAddr = unhashed
// city/state/zip/country for Google; plainMeta = external_id + device/click IDs (unhashed).
const hashedItems = $('Hash identifier (SHA-256)').all().map((i) => i.json);
const deals = $('Read backend conversions (example rows)').all().map((i) => i.json);
const byDeal = {};
for (const h of hashedItems) { (byDeal[h.dealIdx] = byDeal[h.dealIdx] || {})[h.fieldKey] = h.hashedVal; }
return deals.map((d, idx) => {
  const plainMeta = {};
  for (const k of PLAIN_META) { const v = (d[k] == null ? '' : String(d[k]).trim()); if (v) plainMeta[k] = v; }
  return { json: {
    destination: (d.destination || 'both'),
    value: Number(d.value), currency: d.currency || 'USD',
    event_name: d.event_name || 'Purchase', event_time: Number(d.event_time) || 0, event_id: d.event_id || ('conv_' + idx),
    hashed: byDeal[idx] || {},
    plainAddr: { city: norm('ct', d.city), state: norm('st', d.state), zip: norm('zp', d.zip), country: norm('country', d.country) },
    plainMeta,
  } };
});

// Build the Meta Conversions API batch. Config comes from the Set config node (read via
// the node reference below), so this runs cleanly under n8n's task runner. Set
// test_event_code in config to test via Meta Test Events safely.
const cfg = $('Set config (ids & versions)').first().json;
const V = cfg.META_API_VERSION || 'v21.0';
const PIX = (cfg.META_PIXEL_ID || '').trim();
const now = Math.floor(Date.now() / 1000);
const rows = $input.all().map((i) => i.json).filter((d) => d.value != null);
const data = rows.map((d) => {
  const ud = {};
  for (const [k, v] of Object.entries(d.hashed)) ud[k] = [v];
  const pm = d.plainMeta || {};
  if (pm.external_id) ud.external_id = [pm.external_id];
  if (pm.fbc) ud.fbc = pm.fbc;
  if (pm.fbp) ud.fbp = pm.fbp;
  if (pm.client_ip_address) ud.client_ip_address = pm.client_ip_address;
  if (pm.client_user_agent) ud.client_user_agent = pm.client_user_agent;
  return { event_name: d.event_name, event_time: d.event_time > 0 ? d.event_time : now, action_source: 'system_generated', event_id: d.event_id, user_data: ud, custom_data: { value: Number(d.value), currency: d.currency } };
});
const payload = { data };
if (cfg.META_TEST_EVENT_CODE) payload.test_event_code = cfg.META_TEST_EVENT_CODE;
return [{ json: { url: `https://graph.facebook.com/${V}/${PIX}/events`, body: payload, count: data.length } }];

// Build the Google Ads Enhanced Conversions upload. Config from the Set config node reference.
const cfg = $('Set config (ids & versions)').first().json;
const GV = cfg.GOOGLE_ADS_API_VERSION || 'v18';
const CID = (cfg.GOOGLE_ADS_CUSTOMER_ID || '').replace(/-/g, '');
const CA = cfg.GOOGLE_ADS_CONVERSION_ACTION;
const iso = (t) => new Date((Number(t) > 0 ? Number(t) * 1000 : Date.now())).toISOString().replace('T', ' ').replace(/\..*/, '+00:00');
const rows = $input.all().map((i) => i.json).filter((d) => d.value != null);
const conversions = rows.map((d) => {
  const ui = [];
  if (d.hashed.em) ui.push({ hashedEmail: d.hashed.em });
  if (d.hashed.ph) ui.push({ hashedPhoneNumber: d.hashed.ph });
  const a = d.plainAddr || {}; const addr = {};
  if (d.hashed.fn) addr.hashedFirstName = d.hashed.fn;
  if (d.hashed.ln) addr.hashedLastName = d.hashed.ln;
  if (a.city) addr.city = a.city;
  if (a.state) addr.state = a.state;
  if (a.zip) addr.postalCode = a.zip;
  if (a.country) addr.countryCode = a.country.toUpperCase();
  if (Object.keys(addr).length) ui.push({ addressInfo: addr });
  return { conversionAction: CA, conversionDateTime: iso(d.event_time), conversionValue: Number(d.value), currencyCode: d.currency, userIdentifiers: ui };
});
return [{ json: { url: `https://googleads.googleapis.com/${GV}/customers/${CID}:uploadClickConversions`, body: { conversions, partialFailure: true }, count: conversions.length } }];
